const all = rowsOf('Review posts');
const posts = all.filter((p) => p.status === 'published' && p.published_at && parseDt(p.published_at) >= from).map((p) => {
  const o = outcomes.filter((x) => x.post_id === p.Id).map((x) => ({ checkpoint: x.checkpoint, reach: Number(x.reach) || 0, reactions: Number(x.reactions) || 0, comments: Number(x.comments) || 0, shares: Number(x.shares) || 0 }));
  return { post_id: p.Id, content_type: p.content_type, text: p.approved_text || p.text || '', published_at: iso(parseDt(p.published_at)), slot: p.slot || parseDt(p.published_at).toFormat('ccc-HH:mm').toLowerCase(),
    settled: o.some((x) => x.checkpoint === '7d'), owner_edited: Boolean(p.owner_edited), owner_rejected: false, outcomes: o };
});
const rejected = all.filter((p) => p.status === 'rejected' && p.created_at && parseDt(p.created_at) >= from).length;
const median = (xs) => { if (!xs.length) return null; const a = [...xs].sort((x, y) => x - y); const m = Math.floor(a.length / 2); return a.length % 2 ? a[m] : (a[m - 1] + a[m]) / 2; };
const reach24 = (p) => (p.outcomes.find((o) => o.checkpoint === '24h') || {}).reach;
const task = {
  period: { from: iso(from), to: iso(now) },
  posts,
  active_lessons: rowsOf('Review lessons').filter((l) => l.status === 'active').map((l) => ({ id: l.Id, lesson: l.lesson, evidence: l.evidence || '', written_at: l.written_at ? iso(parseDt(l.written_at)) : iso(now) })),
  slots: linesOf(s.slots).map((slot) => { const ps = posts.filter((p) => p.slot === slot); return { slot, posts_behind_it: ps.length, median_reach: median(ps.map(reach24).filter((x) => x !== undefined)) }; }),
  rejected_in_period: rejected,
  now: iso(now),
};
const settled = posts.filter((p) => p.settled).length;
// Under two settled posts there is nothing to learn: say so without spending the call.
if (settled < 2) return [{ json: { task, body: null, report: `Tuần này mới có ${settled} bài đủ 7 ngày, chưa đủ để rút ra gì hết. Em hong đổi gì.` } }];
return [{ json: { task, body: JSON.stringify({ model: 'moonshotai/kimi-k3', response_format: { type: 'json_object' }, usage: { include: true }, messages: [{ role: 'system', content: $('Review prompts').first().json['review'] }, { role: 'user', content: JSON.stringify(task) }] }), report: '' } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => ($(name).isExecuted ? $(name).all() : [])
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const linesOf = (v) => String(v || '').split('\n').map((s) => s.trim()).filter(Boolean);
// NocoDB returns DateTime in UTC as "2026-09-17 13:00:00+00:00".
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const iso = (dt) => dt.setZone(TZ).toISO({ suppressMilliseconds: true });

const parse = (r) => {
  const c = (((r || {}).choices || [])[0] || {}).message?.content;
  if (typeof c !== 'string') return { error: ((r || {}).error || {}).message || 'no answer from the model' };
  try { return { value: JSON.parse(c.trim().replace(/^```(?:json)?\s*|\s*```$/g, '')) }; }
  catch (e) { return { error: `not JSON: ${c.slice(0, 200)}` }; }
};
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
// Offers written, queued or published this month count toward the two a month.
const offersThisMonth = (posts) => {
  const month = DateTime.now().setZone(TZ).toFormat('yyyy-MM');
  return posts.filter((p) => p.content_type === 'offer' && !['rejected', 'failed'].includes(p.status)
    && parseDt(p.scheduled_for || p.created_at).toFormat('yyyy-MM') === month).length;
};

// G8: one claim, at most 250 characters, two settled posts behind it, at most 10 active; slot changes above the floor.
const t = $('Review task').first().json;
const s = settingsOf('Review settings');
const settingsRows = rowsOf('Review settings');
const now = iso(DateTime.now());
if (!$('Review').isExecuted) return [{ json: { report: t.report, creates: [], retires: [], slots: null } }];
const p = parse($('Review').first().json);
if (p.error) throw new Error(`review: ${p.error}`);
const v = p.value;
const dropped = [];
const settled = new Set(t.task.posts.filter((x) => x.settled).map((x) => x.post_id));
const active = new Map(t.task.active_lessons.map((l) => [l.id, l]));
const retires = [];
for (const r of Array.isArray(v.lessons_retire) ? v.lessons_retire : []) {
  if (active.has(Number(r.id)) && String(r.why || '').length >= 10) { retires.push({ _id: Number(r.id), status: 'retired', retired_at: now, retired_why: String(r.why).slice(0, 1000) }); active.delete(Number(r.id)); }
  else dropped.push(`hong cho lesson #${r.id} nghỉ: hong có lesson đó đang chạy, hoặc thiếu lý do`);
}
const creates = [];
for (const l of Array.isArray(v.lessons_new) ? v.lessons_new : []) {
  const text = String((l && l.lesson) || '').trim();
  const ids = [...new Set(((l && l.evidence && l.evidence.post_ids) || []).map(Number))].filter((id) => settled.has(id));
  if (!text || text.length > 250) { dropped.push(`bỏ lesson "${text.slice(0, 60)}…": dài quá 250 ký tự hoặc rỗng`); continue; }
  if (ids.length < 2) { dropped.push(`bỏ lesson "${text.slice(0, 60)}": cần ít nhất 2 bài đã đủ 7 ngày làm bằng chứng`); continue; }
  if (l.retires && active.has(Number(l.retires))) { retires.push({ _id: Number(l.retires), status: 'retired', retired_at: now, retired_why: `thay bằng: ${text}` }); active.delete(Number(l.retires)); }
  if (active.size + creates.length >= 10) { dropped.push(`bỏ lesson "${text.slice(0, 60)}": đã đủ 10 lesson đang chạy`); continue; }
  creates.push({ lesson: text, evidence: `bài #${ids.join(', #')}: ${String(l.evidence.numbers || '').slice(0, 800)}`, status: 'active', written_at: now });
}
let slots = linesOf(s.slots);
const floor = Number(s.slot_floor) || 4;
for (const c of Array.isArray(v.slot_changes) ? v.slot_changes : []) {
  const ok = slots.includes(c.from) && /^(mon|tue|wed|thu|fri|sat|sun)-([01]\d|2[0-3]):[0-5]\d$/.test(c.to) && !slots.includes(c.to);
  if (!ok || !(Number(c.n) >= floor)) { dropped.push(`hong đổi khung ${c.from} → ${c.to}: ${ok ? `mới có ${c.n} bài, cần ${floor}` : 'khung giờ hong hợp lệ'}`); continue; }
  slots = slots.map((x) => (x === c.from ? c.to : x));
}
const slotRow = settingsRows.find((r) => r.key === 'slots');
const changedSlots = slots.join('\n') !== linesOf(s.slots).join('\n') && slotRow ? { _id: slotRow.Id, value: slots.join('\n') } : null;
const report = [String(v.report || '').trim(), v.cannot_tell ? `Hong biết được: ${v.cannot_tell}` : '', dropped.length ? `Code chặn lại:\n- ${dropped.join('\n- ')}` : ''].filter(Boolean).join('\n\n');
return [{ json: { report, creates, retires, slots: changedSlots } }];

